--- index.html
+++ index.html
@@ -46,9 +46,9 @@
 function showEnd(win){$('#menu').classList.remove('hide');$('#menu').innerHTML=`<div class="title"><p>${win?'THE FALSE GOD HAS FALLEN':'THE KEEP CLAIMS ANOTHER SOUL'}</p><h1>${win?'VICTORY':'OBLIVION'}</h1><button id="again">${win?'DESCEND AGAIN':'RISE AGAIN'}</button></div>`;$('#again').onclick=()=>location.reload()}
 $('#start').onclick=()=>{$('#menu').classList.add('hide');running=true};
 function fireball(){if(!running||gameOver)return;const mat=new THREE.MeshBasicMaterial({color:0xff5a24});const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.28,1),mat);m.position.copy(boss.position);m.position.y=3;scene.add(m);const dir=player.position.clone().sub(m.position).normalize();projectiles.push({m,dir,speed:phase===3?9:7})}
 let bossShot=0,bossMove=0;
-function animate(){requestAnimationTime=requestAnimationFrame(animate);const dt=Math.min(.033,(performance.now()-time)/1000||.016);time=performance.now();if(running&&!gameOver){attackCd=Math.max(0,attackCd-dt);dashCd=Math.max(0,dashCd-dt);skillCd=Math.max(0,skillCd-dt);stamina=Math.min(100,stamina+18*dt);$('#stamina i').style.width=stamina+'%';bossShot-=dt;if(bossShot<=0){fireball();bossShot=phase===3?.85:phase===2?1.15:1.7}
+function animate(){requestAnimationFrame(animate);const dt=Math.min(.033,(performance.now()-time)/1000||.016);time=performance.now();if(running&&!gameOver){attackCd=Math.max(0,attackCd-dt);dashCd=Math.max(0,dashCd-dt);skillCd=Math.max(0,skillCd-dt);stamina=Math.min(100,stamina+18*dt);$('#stamina i').style.width=stamina+'%';bossShot-=dt;if(bossShot<=0){fireball();bossShot=phase===3?.85:phase===2?1.15:1.7}
 let mx=(keys.KeyD||0)-(keys.KeyA||0)+stickX,my=(keys.KeyS||0)-(keys.KeyW||0)+stickY;const len=Math.hypot(mx,my);if(len>.1){mx/=Math.max(1,len);my/=Math.max(1,len);const sp=dt*(keys.ShiftLeft?7:5.2);player.position.x+=mx*sp;player.position.z+=my*sp;player.rotation.y=Math.atan2(mx,my);player.position.x=THREE.MathUtils.clamp(player.position.x,-23,23);player.position.z=THREE.MathUtils.clamp(player.position.z,-16,16)}bossMove+=dt;if(bossMove>2.5&&phase>1){bossMove=0;boss.position.x=THREE.MathUtils.clamp(boss.position.x+(Math.random()-.5)*7,-14,14)}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.m.position.addScaledVector(p.dir,dt*p.speed);if(p.m.position.distanceTo(player.position.clone().setY(p.m.position.y))<.75){damagePlayer(12);scene.remove(p.m);projectiles.splice(i,1)}else if(p.m.position.length()>40){scene.remove(p.m);projectiles.splice(i,1)}}
 for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.t+=dt;e.m.scale.setScalar(1+e.t*5);e.m.material.opacity=Math.max(0,.8-e.t);if(e.t>1){scene.remove(e.m);effects.splice(i,1)}}}
 // boss idle
